using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using DotReticulum.Applications.Rngit;
using DotReticulum.Core;

namespace DotReticulum.Applications.Tests;

public sealed class RngcsTests
{
    // Generated by running actual rnid.py/commitsigs.py from hosted upstream
    // a29bfb51c468945c96a1ee22cae0114e993e2391, RNS 1.5.7.
    // GenerateRngcsVectors.py verifies actual imports with reference_environment.py.
    // Source SHA-256s and generation provenance are in Fixtures/rngcs.json.
    private static JsonDocument Vectors() =>
        JsonDocument.Parse(File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory, "Fixtures", "rngcs.json")));

    [Fact]
    public void SourceProvenance_IsPinned()
    {
        using var vectors = Vectors();
        Assert.Equal("a29bfb51c468945c96a1ee22cae0114e993e2391", vectors.RootElement.GetProperty("upstream").GetString());
        Assert.Equal("1.5.7", vectors.RootElement.GetProperty("rns_version").GetString());
        Assert.Equal("f4a05c0db1099d60a032f57e40b457edfdd60e30248ae5c4c25f0542bbbaa0fc",
            vectors.RootElement.GetProperty("commitsigs_sha256").GetString());
        Assert.Equal("faee0d8acb4263f10812fa378085f2653b2453f584b4a33f2018c7797885f8c8",
            vectors.RootElement.GetProperty("rnid_sha256").GetString());
    }

    [Fact]
    public void UpstreamSigningVectors_MatchEveryByteIncludingEmbeddedReleaseMetadata()
    {
        using var vectors = Vectors();
        using var identity = Identity.FromPrivateKey(Convert.FromHexString(vectors.RootElement.GetProperty("public_test_private_key").GetString()!));
        foreach (var vector in vectors.RootElement.GetProperty("rsg_vectors").EnumerateArray())
        {
            var message = Convert.FromHexString(vector.GetProperty("message").GetString()!);
            var metadata = new Dictionary<object, object?>();
            if (vector.GetProperty("meta").ValueKind == JsonValueKind.Object)
            {
                foreach (var entry in vector.GetProperty("meta").EnumerateObject()) metadata[entry.Name] = entry.Value.GetString();
                metadata["signer"] = new byte[16];
                metadata["pubkey"] = new byte[64];
            }
            var rsg = RngitSignatures.CreateRsg(identity, message, vector.GetProperty("embed").GetBoolean(), metadata);
            Assert.Equal(vector.GetProperty("rsg").GetString(), Convert.ToHexStringLower(rsg));
            if (vector.TryGetProperty("armor", out var armor))
            {
                var encoded = RngitSignatures.CreateSshSignature(identity, rsg);
                Assert.Equal(armor.GetString(), RngitSignatures.ArmorSshSignature(encoded));
                Assert.Equal(encoded, RngitSignatures.UnarmorSshSignature(armor.GetString()!));
            }
            Assert.Equal(rsg, vector.GetProperty("embed").GetBoolean()
                ? RngitSignatures.CreateRsg(identity, message, true, metadata)
                : RngitSignatures.CreateRsgFromHash(identity, SHA256.HashData(message), metadata));
        }
    }

    [Fact]
    public void UpstreamValidationDifferentials_SeparateStructureCryptographyAndTrustedSigner()
    {
        using var vectors = Vectors();
        foreach (var vector in vectors.RootElement.GetProperty("validations").EnumerateArray())
        {
            var rsg = Convert.FromHexString(vector.GetProperty("rsg").GetString()!);
            var message = Convert.FromHexString(vector.GetProperty("message").GetString()!);
            var required = vector.GetProperty("required").GetString();
            var validation = RngitSignatures.ValidateRsg(rsg, message,
                required is null ? [] : Convert.FromHexString(required));
            if (vector.GetProperty("intentional_key_hardening").GetBoolean())
            {
                Assert.False(validation.IsValid);
                if (required is null) Assert.True(vector.GetProperty("valid").GetBoolean());
            }
            else
                Assert.True(vector.GetProperty("valid").GetBoolean() == validation.IsValid,
                    $"{vector.GetProperty("name")}/{vector.GetProperty("required_name")}");
        }
    }

    [Fact]
    public async Task UpstreamCliDifferentials_CompareExitStdoutStderr()
    {
        using var vectors = Vectors();
        var root = NewDirectory();
        try
        {
            await File.WriteAllBytesAsync(Path.Combine(root, "key"),
                Convert.FromHexString(vectors.RootElement.GetProperty("public_test_private_key").GetString()!));
            var commit = vectors.RootElement.GetProperty("rsg_vectors").EnumerateArray()
                .First(v => v.GetProperty("name").GetString() == "commit");
            await File.WriteAllBytesAsync(Path.Combine(root, "file"), Convert.FromHexString(commit.GetProperty("message").GetString()!));
            foreach (var vector in vectors.RootElement.GetProperty("cli").EnumerateArray())
            {
                var name = vector.GetProperty("name").GetString()!;
                var signature = vector.GetProperty("signature").GetString();
                if (signature is not null) await File.WriteAllTextAsync(Path.Combine(root, "sig"), signature);
                var args = vector.GetProperty("args").EnumerateArray().Select(v => v.GetString()!)
                    .Select(a => a.StartsWith('{') ? Path.Combine(root, a[1..^1]) : a).ToArray();
                var result = await Run(args, Convert.FromHexString(vector.GetProperty("message").GetString()!));
                Assert.True(vector.GetProperty("code").GetInt32() == result.Code, $"{name}: {result}");
                if (vector.TryGetProperty("intentional_key_hardening", out var hardened) && hardened.GetBoolean())
                {
                    Assert.StartsWith("Commit not signed by author", vector.GetProperty("output").GetString());
                    Assert.Equal("", result.Output);
                    Assert.Equal("Invalid signature\n", Normalize(result.Error));
                    continue;
                }
                Assert.True(Normalize(vector.GetProperty("output").GetString()!.Replace("{root}", root, StringComparison.Ordinal)) == Normalize(result.Output), $"{name}: {result}");
                var upstreamError = Normalize(vector.GetProperty("error").GetString()!.Replace("{root}", root, StringComparison.Ordinal));
                // Upstream leaks Python exceptions for malformed envelopes and empty-message verify.
                // This implementation reports a bounded, deterministic failure instead of a traceback.
                if (upstreamError.StartsWith("UPSTREAM_EXCEPTION:", StringComparison.Ordinal))
                    Assert.Equal("Invalid signature\n", Normalize(result.Error));
                else if (name.StartsWith("legacy-find-", StringComparison.Ordinal)
                    || name.StartsWith("truncated-rsg-find-", StringComparison.Ordinal)
                    || name.StartsWith("malformed-envelope-find-", StringComparison.Ordinal)
                    || name.StartsWith("structure-only-find-", StringComparison.Ordinal)
                    || name.StartsWith("truthy-array-find-", StringComparison.Ordinal)
                    || name.StartsWith("empty-map-find-", StringComparison.Ordinal)
                    || name.StartsWith("duplicate-key-find-", StringComparison.Ordinal)
                    || name.StartsWith("invalid-utf8-find-", StringComparison.Ordinal)
                    || name.StartsWith("missing-signer-find-", StringComparison.Ordinal))
                    Assert.StartsWith("Could not determine signer identity:", result.Error);
                else
                    Assert.True(upstreamError == Normalize(result.Error), $"{name}: expected {upstreamError}, got {result.Error}");
                if (vector.TryGetProperty("file_signature", out var fileSignature))
                    Assert.Equal(fileSignature.GetString(), await File.ReadAllTextAsync(Path.Combine(root, "file.sig")));
            }
        }
        finally { Directory.Delete(root, true); }
    }

    [Fact]
    public void ExtractionAndCrypto_DoNotGrantTrustOrValidateEmbeddedMessages()
    {
        using var identity = Identity.Generate();
        var rsg = RngitSignatures.CreateRsg(identity, "actual artifact"u8, true,
            new Dictionary<object, object?> { ["release"] = "v1" });
        var extracted = Assert.IsType<Dictionary<object, object?>>(RngitSignatures.ExtractRsg(rsg));
        Assert.Equal("actual artifact"u8.ToArray(), extracted["message"]);
        Assert.True(RngitSignatures.ValidateRsgHash(rsg, SHA256.HashData("actual artifact"u8), identity.Hash).IsValid);
        using var stranger = Identity.Generate();
        Assert.False(RngitSignatures.ValidateRsgHash(rsg, SHA256.HashData("actual artifact"u8), stranger.Hash).IsValid);
        Assert.False(RngitSignatures.ValidateRsg(rsg, "different artifact"u8).IsValid);
        rsg[0] ^= 1;
        Assert.NotNull(RngitSignatures.ExtractRsg(rsg));
        Assert.False(RngitSignatures.ValidateRsg(rsg, "actual artifact"u8).IsValid);
    }

    [Fact]
    public void CryptoHardening_RejectsLowOrderNoncanonicalAndInvalidKeys()
    {
        using var identity = Identity.Generate();
        foreach (var index in new[] { 0, 32 })
        {
            var pub = identity.ExportPublicKey();
            pub.AsSpan(index, 32).Clear();
            var data = new Dictionary<object, object?>
            {
                ["hashtype"] = "sha256",
                ["hash"] = SHA256.HashData("artifact"u8),
                ["meta"] = new Dictionary<object, object?> { ["signer"] = identity.Hash, ["pubkey"] = pub }
            };
            var envelope = MsgPack.Pack(data);
            Assert.False(RngitSignatures.ValidateRsg([.. identity.Sign(envelope), .. envelope], "artifact"u8).IsValid);
        }
    }

    [Fact]
    public void Parsing_BoundsLengthOverflowTruncationDepthAndVersion()
    {
        Assert.Throws<FormatException>(() => RngitSignatures.ParseSshSignature("not SSHSIG"u8));
        Assert.Throws<FormatException>(() => RngitSignatures.ParseSshSignature("SSHSIG"u8));
        Assert.Throws<FormatException>(() => RngitSignatures.ParseSshSignature(
            [.. "SSHSIG"u8, 0, 0, 0, 1, 255, 255, 255, 255]));
        Assert.Throws<FormatException>(() => RngitSignatures.ParseSshSignature(new byte[RngitSignatures.MaximumSignatureBytes + 1]));
        Assert.Throws<FormatException>(() => RngitSignatures.UnarmorSshSignature(new string('a', RngitSignatures.MaximumArmoredCharacters + 1)));
        Assert.Null(RngitSignatures.ExtractRsg(new byte[RngitSignatures.MaximumSignatureBytes + 1]));
        Assert.Null(RngitSignatures.ExtractRsg([.. new byte[64], .. Enumerable.Repeat((byte)0x91, 100), 0xc0]));
        Assert.Null(RngitSignatures.ExtractRsg([.. new byte[64], 0xdf, 255, 255, 255, 255]));
        Assert.Null(RngitSignatures.ExtractRsg([.. new byte[64], 0x82, 0xa1, (byte)'a', 0, 0xa1, (byte)'a', 1]));
        Assert.Null(RngitSignatures.ExtractRsg([.. new byte[64], 0x81, 0xa1, (byte)'a', 0xa1, 255]));
        Assert.False(RngitSignatures.ValidateRsgHash([], new byte[31]).IsValid);
        Assert.False(RngitSignatures.ValidateRsgHash([], new byte[32], new byte[15]).IsValid);
        using var identity = Identity.Generate();
        Assert.Throws<ArgumentException>(() => RngitSignatures.CreateRsg(identity, new byte[RngitSignatures.MaximumMessageBytes + 1]));
        Assert.Throws<ArgumentException>(() => RngitSignatures.CreateRsgFromHash(identity, new byte[31]));
    }

    [Fact]
    public async Task BinaryInputAndFileInput_AreBoundedAndCancellationAware()
    {
        var root = NewDirectory();
        try
        {
            using var identity = Identity.Generate();
            var key = Path.Combine(root, "key");
            await File.WriteAllBytesAsync(key, identity.ExportPrivateKey());
            var oversized = new byte[RngitSignatures.MaximumMessageBytes + 1];
            var stdin = await Run(["-Y", "sign", "-f", key], oversized);
            Assert.Equal(1, stdin.Code);
            Assert.Contains("exceeds", stdin.Error);
            var path = Path.Combine(root, "oversized");
            await File.WriteAllBytesAsync(path, oversized);
            var file = await Run(["-Y", "sign", "-f", key, path], []);
            Assert.Equal(1, file.Code);
            Assert.False(File.Exists(path + ".sig"));
            var invalidKey = Path.Combine(root, "invalid-key");
            await File.WriteAllBytesAsync(invalidKey, new byte[65]);
            Assert.Equal(1, (await Run(["-Y", "sign", "-f", invalidKey], [])).Code);
            using var stop = new CancellationTokenSource();
            await stop.CancelAsync();
            using var input = new MemoryStream();
            using var output = new StringWriter();
            using var error = new StringWriter();
            Assert.Equal(1, await RngcsApp.RunAsync(["-Y", "sign", "-f", key], input, output, error, stop.Token));
            Assert.Contains("cancelled", error.ToString());
            Assert.Equal("", output.ToString());
            using var blockedInput = new CancellationStream();
            using var timeout = new CancellationTokenSource(TimeSpan.FromMilliseconds(50));
            Assert.Equal(1, await RngcsApp.RunAsync(["-Y", "sign", "-f", key], blockedInput, output, error, timeout.Token));
            Assert.False(blockedInput.WasDisposed);
        }
        finally { Directory.Delete(root, true); }
    }

    [Theory]
    [InlineData(new[] { "-Y", "unknown" }, 2)]
    [InlineData(new[] { "-Y", "sign", "-f" }, 2)]
    [InlineData(new[] { "-bad" }, 2)]
    [InlineData(new string[0], 2)]
    [InlineData(new[] { "-Y", "sign", "-bad" }, 1)]
    public async Task InvalidArguments_FailWithoutMutations(string[] args, int code)
    {
        var result = await Run(args, []);
        Assert.Equal(code, result.Code);
        Assert.NotEmpty(result.Error);
        Assert.Empty(result.Output);
    }

    [Fact]
    public async Task Help_DisclosesIgnoredArgumentsFixedNamespaceAndTrustLimit()
    {
        var result = await Run(["--help"], []);
        Assert.Equal(0, result.Code);
        Assert.Contains("ignored", result.Output);
        Assert.Contains("not allowed-signers trust", result.Output);
        Assert.Contains("16 MiB", result.Output);
    }

    private static string Normalize(string text) => text.Replace("\r\n", "\n", StringComparison.Ordinal);

    private static string NewDirectory() => Directory.CreateDirectory(
        Path.Combine(AppContext.BaseDirectory, "rngcs-test-" + Guid.NewGuid().ToString("N"))).FullName;

    private static async Task<(int Code, string Output, string Error)> Run(string[] args, byte[] message)
    {
        using var input = new MemoryStream(message);
        using var output = new StringWriter();
        using var error = new StringWriter();
        var code = await RngcsApp.RunAsync(args, input, output, error, CancellationToken.None);
        return (code, output.ToString(), error.ToString());
    }

    private sealed class CancellationStream : Stream
    {
        public bool WasDisposed { get; private set; }
        public override bool CanRead => true;
        public override bool CanSeek => false;
        public override bool CanWrite => false;
        public override long Length => throw new NotSupportedException();
        public override long Position { get => throw new NotSupportedException(); set => throw new NotSupportedException(); }
        public override int Read(byte[] buffer, int offset, int count) => throw new InvalidOperationException("Synchronous read is forbidden.");
        public override async ValueTask<int> ReadAsync(Memory<byte> buffer, CancellationToken cancellationToken = default)
        {
            await Task.Delay(Timeout.InfiniteTimeSpan, cancellationToken);
            return 0;
        }
        public override void Flush() => throw new NotSupportedException();
        public override long Seek(long offset, SeekOrigin origin) => throw new NotSupportedException();
        public override void SetLength(long value) => throw new NotSupportedException();
        public override void Write(byte[] buffer, int offset, int count) => throw new NotSupportedException();
        protected override void Dispose(bool disposing) { WasDisposed = true; base.Dispose(disposing); }
    }
}
